INSERT INTO service_catalog(id,category,icon,title_en,title_ne,description_en,description_ne,note_en,note_ne,items_json,sort_order,pricing_mode) VALUES('business-pan','government','building','Business PAN assistance','व्यावसायिक PAN सहयोग','Start your Business PAN enquiry with Nath. We review your situation before preparing the next steps.','नाथसँग व्यावसायिक PAN सम्बन्धी अनुरोध सुरु गर्नुहोस्। अर्को चरणअघि तपाईंको अवस्था बुझ्छौँ।','Our team confirms the applicable process and charges before work starts. Official decisions remain with the authority. Do not send document numbers or uploads in the initial request.','कामअघि टोलीले सम्बन्धित प्रक्रिया र शुल्क पुष्टि गर्छ। आधिकारिक निर्णय सम्बन्धित निकायले गर्छ। प्रारम्भिक अनुरोधमा कागजात नम्बर वा कागजात नपठाउनुहोस्।','[["New registration enquiry","नयाँ दर्तासम्बन्धी जानकारी"],["Existing PAN or correction guidance","पहिलेको PAN वा सुधारसम्बन्धी मार्गदर्शन"],["Application follow-up help","आवेदनको जानकारी लिन सहयोग"]]',-10,'quote') ON CONFLICT(id) DO NOTHING;
